export const FAQ_ITEMS = [
  { id: 'faq-1', question: 'How does the Match Score work?', answer: 'Your match score is calculated by comparing your profile (education level, GPA, field of study, nationality, etc.) against each opportunity\'s requirements. A 100% match means you meet all listed criteria. We also suggest steps to improve your match score for opportunities you\'re interested in.' },
  { id: 'faq-2', question: 'Is OpportunityHub free to use?', answer: 'Yes! OpportunityHub is completely free for all Nigerian students. We believe every student deserves access to information about opportunities. Premium features like AI CV review and unlimited document storage may be offered in the future.' },
  { id: 'faq-3', question: 'How do I improve my match score?', answer: 'Click on any opportunity to see your detailed match breakdown. For each missing requirement, we provide a "Build Missing Skills" button that links to relevant learning roadmaps or resources.' },
  { id: 'faq-4', question: 'Are the opportunities on the platform verified?', answer: 'Yes, our team manually verifies every opportunity posted on OpportunityHub. We check official sources, confirm deadlines, and update information regularly.' },
  { id: 'faq-5', question: 'How does the streak system work?', answer: 'You set your own learning schedule (e.g., 30 minutes on Mon, Wed, Fri). When you meet your goal on a scheduled day, your streak increases. There\'s no penalty for non-scheduled days!' },
  { id: 'faq-6', question: 'Is my data safe in the Document Vault?', answer: 'Absolutely. All documents are encrypted and stored securely. Only you can access your vault. You can add PIN or biometric protection for extra security.' },
  { id: 'faq-7', question: 'Can I use OpportunityHub on my phone?', answer: 'Yes! OpportunityHub works on any device with a web browser — Android, iPhone, Windows, and Mac. You can install it as an app from your browser for a native-like experience.' },
  { id: 'faq-8', question: 'How do I connect with mentors?', answer: 'Browse the Mentor Directory, find mentors in your field of interest, and send them a message through the app. Mentors are volunteers who\'ve benefited from similar opportunities.' },
  { id: 'faq-9', question: 'What if an opportunity deadline has passed?', answer: 'Expired opportunities are automatically moved to an archive. We\'ll notify you when similar opportunities reopen. You can also set alerts for specific scholarships.' },
  { id: 'faq-10', question: 'How do I report an issue or suggest a feature?', answer: 'Tap "Contact Support" below to reach our team via email or in-app chat. We love hearing from our users and actively implement popular feature requests.' },
];

